import { task, wait, logger, metadata } from "@trigger.dev/sdk/v3";

interface PoApprovalPayload {
  tenantId: string;
  poCode: string;
  amountVnd: number;
  requesterEmail: string;
  payrollBatchIds: string[];
}

export const erpPoApprovalAndPayrollTask = task({
  id: "erp-po-approval-and-payroll",
  maxDuration: 3600,
  retry: { maxAttempts: 3, factor: 2, minTimeoutInMs: 2000 },
  queue: { name: "erp-hitl-ops", concurrencyLimit: 10 },
  run: async (payload: PoApprovalPayload) => {
    logger.info("Khởi chạy luồng duyệt PO bền vững", { poCode: payload.poCode });
    metadata.set("stage", "WAIT_FINANCE_APPROVAL");

    // 1. Tạo Waitpoint Token có thời hạn tối đa 72 giờ — giải phóng hoàn toàn worker container
    const approvalToken = await wait.createToken({
      timeout: "72h",
      tags: [`tenant:${payload.tenantId}`, `po:${payload.poCode}`],
    });

    // 2. Gửi link xác nhận (chứa approvalToken.id) qua ZaloBot cho cấp duyệt
    await fetch(`${process.env.DOMATION_INTERNAL_URL}/api/zalobot/notify-po`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        tenantId: payload.tenantId,
        poCode: payload.poCode,
        amountVnd: payload.amountVnd,
        resumeCallbackUrl: approvalToken.url,
      }),
    });

    // 3. Đóng băng tiến trình tại đây (0% CPU/RAM trong suốt lúc chờ con người bấm nút)
    const decision = await wait.forToken<{ approved: boolean; approverId: string }>(
      approvalToken
    );

    if (!decision.ok || !decision.output.approved) {
      metadata.set("stage", "REJECTED_OR_EXPIRED");
      return { status: "CANCELLED", poCode: payload.poCode };
    }

    // 4. Tỉnh dậy an toàn, ngủ giãn nhịp 5 phút nếu cần chờ chốt sổ trước khi chạy batch
    metadata.set("stage", "GENERATING_PAYROLL_PDF");
    await wait.for({ seconds: 10 });

    const batchResult = await generateSinglePayrollPdfTask.batchTriggerAndWait(
      payload.payrollBatchIds.map((staffId) => ({
        payload: { tenantId: payload.tenantId, staffId, approvedBy: decision.output.approverId },
      }))
    );

    const successCount = batchResult.runs.filter((r) => r.ok).length;
    metadata.set("stage", "COMPLETED");
    return { status: "SYNCED_MISA", poCode: payload.poCode, successCount };
  },
});

export const generateSinglePayrollPdfTask = task({
  id: "generate-single-payroll-pdf",
  queue: { name: "pdf-render-workers", concurrencyLimit: 5 },
  run: async (input: { tenantId: string; staffId: string; approvedBy: string }) => {
    logger.info("Kết xuất PDF phiếu lương và đẩy chứng từ MISA", input);
    return { staffId: input.staffId, pdfReady: true };
  },
});
